/* Dispatch on frame_id, call the matching generated unpack, update meta.
 * Returns 0 on success, -1 if frame_id is unknown, -2 if unpack fails. */
int FEB_CAN_DB_Update(uint32_t frame_id, const uint8_t *data, uint8_t dlc, uint32_t now_ms);

/* Print a one-line summary for each *present* message. */
void FEB_CAN_DB_Print(int (*printf_fn)(const char *fmt, ...));

/* Print one message's full signal breakdown. Returns 0 on match, -1 if name unknown. */
int FEB_CAN_DB_PrintOne(const char *name, int (*printf_fn)(const char *fmt, ...));


